// Package database owns the connection to PostgreSQL and the migration runner.
//
// Two things live here and nothing else: how the pool is opened, and how the
// schema gets to the state db/schema.sql describes. Every query in the app is
// generated by sqlc from that schema, so this package is the only place that
// knows the two exist.
package database

import (
	"context"
	"database/sql"
	"fmt"
	"net/url"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
)

// PoolSize is the maximum number of open connections.
//
// The box this was sized for is small and shared, and a larger pool buys
// nothing: the app is one user's list views, one sync job, and a per-minute
// cron. What a bigger pool *costs* is real -- each connection is a Postgres
// backend, and the host has a global cap.
const PoolSize = 5

// applicationName shows up in pg_stat_activity, which is how you tell this
// application's connections apart from anything else on a shared host.
const applicationName = "ghostmplay-api"

// Options configures the pool.
type Options struct {
	// URL is the raw DATABASE_URL. Required.
	URL string
	// SSL turns on TLS when the URL does not already say. Only a managed
	// external database needs it; a database on localhost does not.
	SSL bool
	// MaxConns overrides PoolSize. Zero means PoolSize.
	MaxConns int
	// ConnMaxLifetime is how long a connection may be reused. Zero means no
	// limit, which is what the Node implementation did.
	ConnMaxLifetime time.Duration
}

// Config is a validated Options, with the DSN already assembled.
type Config struct {
	DSN      string
	MaxConns int
	MaxIdle  int
	Lifetime time.Duration
}

// OpenConfig assembles the DSN from a URL and the flags.
//
// Two settings are appended rather than left to the caller, because getting
// either wrong is quiet: application_name so this app is identifiable in
// pg_stat_activity, and sslmode when TLS was asked for and the URL did not
// specify one.
//
// sslmode=require is the right choice rather than verify-full. It encrypts and
// skips certificate verification, which matches what the Node implementation
// did (rejectUnauthorized: false) and what every managed host's connection
// string assumes. verify-full would additionally need the host's root CA,
// which is not something a shared or managed database hands you by default, and
// a deployment that fails to boot over a certificate chain is worse than one
// that is trusting a known host.
func OpenConfig(opts Options) (Config, error) {
	if opts.URL == "" {
		return Config{}, fmt.Errorf("database: URL is required")
	}

	maxConns := opts.MaxConns
	if maxConns <= 0 {
		maxConns = PoolSize
	}

	dsn, err := appendParams(opts.URL, map[string]string{
		"application_name": applicationName,
	})
	if err != nil {
		return Config{}, err
	}

	if opts.SSL && !hasParam(dsn, "sslmode") {
		dsn, err = appendParams(dsn, map[string]string{"sslmode": "require"})
		if err != nil {
			return Config{}, err
		}
	}

	return Config{
		DSN:      dsn,
		MaxConns: maxConns,
		MaxIdle:  maxConns,
		Lifetime: opts.ConnMaxLifetime,
	}, nil
}

// Open connects and verifies the connection is usable.
//
// The ping is not optional politeness. On Voroa a service is only reported live
// once it answers, and a pool that is configured but cannot reach the database
// turns a clear startup failure into a service that looks healthy until the
// first request. Failing here means the deploy reports "failed to start" with a
// reason, which is the outcome that can actually be acted on.
func Open(ctx context.Context, opts Options) (*sql.DB, error) {
	cfg, err := OpenConfig(opts)
	if err != nil {
		return nil, err
	}

	db, err := sql.Open("pgx", cfg.DSN)
	if err != nil {
		return nil, fmt.Errorf("database: open: %w", err)
	}

	db.SetMaxOpenConns(cfg.MaxConns)
	db.SetMaxIdleConns(cfg.MaxIdle)
	db.SetConnMaxLifetime(cfg.Lifetime)

	pingCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := db.PingContext(pingCtx); err != nil {
		db.Close()
		return nil, fmt.Errorf("database: ping: %w", err)
	}

	return db, nil
}

// Ping is the /api/health probe. It uses a fresh timeout rather than the
// caller's context because a health check that inherits a request deadline
// reports "down" for a reason that has nothing to do with the database.
func Ping(ctx context.Context, db *sql.DB) error {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	return db.PingContext(ctx)
}

// appendParams adds query parameters to a URL, preserving any already present.
func appendParams(raw string, params map[string]string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("database: parse connection URL: %w", err)
	}
	if u.Scheme != "postgres" && u.Scheme != "postgresql" {
		return "", fmt.Errorf("database: unsupported URL scheme %q, want postgres", u.Scheme)
	}
	q := u.Query()
	for k, v := range params {
		q.Set(k, v)
	}
	u.RawQuery = q.Encode()
	return u.String(), nil
}

func hasParam(raw, key string) bool {
	u, err := url.Parse(raw)
	if err != nil {
		return false
	}
	return u.Query().Has(key)
}
